const cache=new Map();
async function places(q){if(q.length<2)return [];if(cache.has(q))return cache.get(q);const r=await fetch('https://geocoding-api.open-meteo.com/v1/search?name='+encodeURIComponent(q.split(',')[0].trim())+'&count=20&language=en&format=json',{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('Location service unavailable');const a=(await r.json()).results||[];const suffix=normalize(q.split(',').slice(1).join(',')).replace(/^ny$/,'new york');const sorted=a.sort((x,y)=>Number(normalize([y.admin1,y.country].join(' ')).includes(suffix))-Number(normalize([x.admin1,x.country].join(' ')).includes(suffix)));cache.set(q,sorted);return sorted;}
const placeLabel=x=>[x.name,x.admin1,x.country].filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).join(', ');
for(const id of ['origin','destination']){const el=document.getElementById(id);let timer;el.addEventListener('input',()=>{clearTimeout(timer);const q=el.value.trim();timer=setTimeout(async()=>{try{const resolved=id==='destination'?await resolveDestination(q):null;const a=resolved?(resolved.country?[{name:resolved.country}]:resolved.places):await places(q);if(el.value.trim()!==q)return;const list=document.getElementById(id+'List');list.replaceChildren(...a.map(x=>{const o=document.createElement('option');o.value=placeLabel(x);return o;}));}catch(e){document.getElementById(id+'Status').textContent='Location lookup temporarily unavailable.';}},450);});}
let airportPromise;
function parseCSV(line){const out=[];let v='',quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(quoted&&line[i+1]==='"'){v+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){out.push(v);v='';}else v+=c;}out.push(v);return out;}
async function airportData(){if(!airportPromise)airportPromise=(async()=>{const r=await fetch('https://raw.githubusercontent.com/davidmegginson/ourairports-data/main/airports.csv',{signal:AbortSignal.timeout(25000)});if(!r.ok)throw Error('Airport data unavailable');const lines=(await r.text()).trim().split(/\r?\n/);const head=parseCSV(lines.shift());const ix=k=>head.indexOf(k);return lines.map(parseCSV).filter(a=>['large_airport','medium_airport'].includes(a[ix('type')])&&a[ix('scheduled_service')]==='yes'&&/^[A-Z]{3}$/.test(a[ix('iata_code')])).map(a=>({code:a[ix('iata_code')],name:a[ix('name')],municipality:a[ix('municipality')],type:a[ix('type')],lat:+a[ix('latitude_deg')],lon:+a[ix('longitude_deg')]}));})().catch(e=>{airportPromise=null;throw e;});return airportPromise;}
function km(a,b){const r=Math.PI/180;const h=Math.sin((b.lat-a.latitude)*r/2)**2+Math.cos(a.latitude*r)*Math.cos(b.lat*r)*Math.sin((b.lon-a.longitude)*r/2)**2;return 6371*2*Math.asin(Math.sqrt(Math.min(1,h)));}
async function nearby(q){const a=await places(q);if(!a.length)throw Error('City not found');const city=a.find(x=>normalize(placeLabel(x))===normalize(q))||a[0];const airports=(await airportData()).map(x=>({...x,distance:km(city,x)})).sort((a,b)=>a.distance-b.distance);const chosen=[...new Map([...airports.slice(0,1),...airports.filter(a=>a.type==='large_airport'&&a.distance<=400).slice(0,4),...airports.slice(0,5)].map(a=>[a.code,a])).values()].slice(0,5);return {city,airports:chosen};}
document.getElementById('suggestAirports').addEventListener('click',async()=>{const status=document.getElementById('airportStatus');status.textContent=' Looking up airports…';try{const {city,airports}=await nearby(document.getElementById('origin').value.trim());const el=document.getElementById('airports');el.value=[...new Set([...el.value.toUpperCase().split(/[,;\s]+/).filter(Boolean),...airports.map(a=>a.code)])].slice(0,5).join(', ');status.textContent=' '+placeLabel(city)+': '+airports.map(a=>a.code+' ('+Math.round(a.distance)+' km)').join(', ')+'. Straight-line distances, not driving routes.';}catch(e){status.textContent=' '+e.message+'. Enter airport codes manually.';}});
async function resolveDestination(q){
 const clean=q.replace(/^(?:trip to|travel to|visit|fly to|go to)\s+/i,'').trim();
 const exact=countryNames.get(normalize(clean));if(exact)return {country:exact,places:[]};
 const parts=clean.split(',').map(x=>x.trim()).filter(Boolean);
 const countryPart=parts.find(x=>countryNames.has(normalize(x)));
 const country=countryPart?countryNames.get(normalize(countryPart)):null;
 const city=countryPart?parts.filter(x=>x!==countryPart)[0]:parts[0];
 if(!city)return {country,places:[]};
 const matches=(await places(city)).filter(x=>normalize(x.name)===normalize(city)&&(!country||normalize(x.country||'')===normalize(country)));
 return {country:null,places:[...new Map(matches.map(x=>[placeLabel(x),x])).values()]};
}
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const codes=s=>[...new Set(s.toUpperCase().split(/[,;\s]+/).filter(Boolean))];
const duration=n=>`${Math.floor(n/60)}h ${n%60}m`;
const today=new Date(); const localDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
$('outbound').min=localDate(today); $('returning').min=localDate(today);
$('outbound').addEventListener('change',()=>{$('returning').min=$('outbound').value;if($('returning').value<=$('outbound').value)$('returning').value='';});
async function arrivalSuggestions(){const q=$('destination').value.trim();if(!q)throw Error('Enter a destination city or arrival airport codes.');const r=await resolveDestination(q);if(r.country)throw Error('Choose a city within '+r.country+' or enter airport codes manually.');const exact=r.places.find(x=>normalize(placeLabel(x))===normalize(q));if(!exact&&r.places.length!==1)throw Error('Select a specific destination city from the suggestions or enter airport codes.');const city=exact||r.places[0];const all=(await airportData()).map(a=>({...a,distance:km(city,a)})).sort((a,b)=>a.distance-b.distance);const selected=all.filter(a=>a.distance<=100).slice(0,3);if(!selected.length)throw Error('No nearby airport found. Enter arrival codes manually.');$('arrival').value=selected.map(a=>a.code).join(', ');$('arrivalStatus').textContent=' '+selected.map(a=>a.code+' ('+Math.round(a.distance)+' km)').join(', ')+' · straight-line distance';return codes($('arrival').value);}
$('suggestArrival').addEventListener('click',async()=>{try{await arrivalSuggestions();}catch(e){$('arrivalStatus').textContent=e.message;}});
$('destination').addEventListener('input',()=>{$('arrival').value='';$('arrivalStatus').textContent='';});
$('origin').addEventListener('input',()=>{$('airports').value='';$('airportStatus').textContent=' Enter codes or use suggestions.';});
// Private, low-volume routing test only. No API token is sent to OSRM.
async function groundRoutes(origin, dep, mpg) {
  const result = new Map();
  try {
    const matches = await places(origin);
    const city = matches.find(x=>normalize(placeLabel(x))===normalize(origin)) || matches[0];
    if (!city || city.country_code !== 'US') return result;
    const airports = (await airportData()).filter(a=>dep.includes(a.code));
    if (!airports.length) return result;
    const coords = [[city.longitude,city.latitude], ...airports.map(a=>[a.lon,a.lat])].map(a=>a.join(',')).join(';');
    const r = await fetch('https://router.project-osrm.org/table/v1/driving/'+coords+'?annotations=distance,duration', {signal:AbortSignal.timeout(20000)});
    if(!r.ok) return result;
    const data=await r.json();
    if(data.code!=='Ok') return result;
    airports.forEach((a,i)=>{
      const k=i+1, d1=data.distances?.[0]?.[k], d2=data.distances?.[k]?.[0], t=data.durations?.[0]?.[k];
      if([d1,d2,t].every(v=>Number.isFinite(v)&&v>=0)) {
        const miles=(d1+d2)/1609.344;
        result.set(a.code,{miles, outMiles:d1/1609.344,backMiles:d2/1609.344,backMinutes:Number.isFinite(data.durations?.[k]?.[0])?Math.round(data.durations[k][0]/60):null,minutes:Math.round(t/60),fuel:miles/mpg*3.50});
      }
    });
  } catch(e) { /* Keep flight results usable on routing failure. */ }
  return result;
}

// EPA vehicle menus; no flight token or API key is sent.
let vehicleGeneration=0, vehicleMpg=null;
const vehicleIds=['vehicleYear','vehicleMake','vehicleModel'];
function resetMenu(id,items=[]){$(id).replaceChildren(new Option('Select…',''),...items.map(x=>new Option(x.text,x.value)));}
async function epa(path,params={}){const r=await fetch('https://www.fueleconomy.gov/ws/rest/vehicle/'+path+'?'+new URLSearchParams(params),{headers:{Accept:'application/json'},signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('EPA lookup unavailable');return r.json();}
async function vehicleMenu(level){const gen=++vehicleGeneration;vehicleMpg=null;for(let i=level;i<3;i++)resetMenu(vehicleIds[i]);$('vehicleStatus').textContent='Loading vehicle data…';try{const params={};if(level>0)params.year=$('vehicleYear').value;if(level>1)params.make=$('vehicleMake').value;if(level>2)params.model=$('vehicleModel').value;if(Object.values(params).some(x=>!x)){$('vehicleStatus').textContent='Select vehicle details above.';return;}const data=await epa('menu/'+['year','make','model','options'][level],params);if(gen!==vehicleGeneration)return;const raw=data.menuItem||[];const items=Array.isArray(raw)?raw:[raw];if(level<3){resetMenu(vehicleIds[level],items);$('vehicleStatus').textContent='Select '+['year','make','model'][level]+'.';return;}const ids=[...new Set(items.map(x=>String(x.value)).filter(x=>/^\d+$/.test(x)))];const ratings=[];for(let i=0;i<ids.length;i+=4){const batch=await Promise.all(ids.slice(i,i+4).map(id=>epa(id)));if(gen!==vehicleGeneration)return;ratings.push(...batch);}const eligible=ratings.filter(d=>/gasoline/i.test(d.fuelType1||'')&&!d.fuelType2&&!/hybrid|electric/i.test(d.atvType||'')&&Number(d.comb08)>0);if(!eligible.length)throw Error('No comparable gasoline ratings');vehicleMpg=Math.round(eligible.reduce((sum,d)=>sum+Number(d.comb08),0)/eligible.length*10)/10;$('vehicleStatus').textContent='Estimated model-average: '+vehicleMpg+' MPG (EPA combined ratings, '+eligible.length+' gasoline configurations; not sales-weighted). Actual MPG may vary.';}catch(e){if(gen===vehicleGeneration)$('vehicleStatus').textContent='Gasoline MPG lookup unavailable. Retry or enter actual gasoline MPG.';}}
for(let i=0;i<3;i++)$(vehicleIds[i]).addEventListener('change',()=>vehicleMenu(i+1));
