function drivingPreference(){if($('carAccess').value==='no')return null;if($('carAccess').value!=='yes')throw Error('Choose whether you have access to a reliable car.');const mode=$('mpgMode').value,mpg=mode==='manual'?Number($('manualMpg').value):mode==='lookup'?vehicleMpg:28;if(!Number.isFinite(mpg)||mpg<1||mpg>150)throw Error('Enter valid MPG or finish the vehicle lookup before searching.');return {mpg,source:mode==='manual'?'user supplied':mode==='lookup'?'EPA model-average estimate':'general assumption'};}

