function rideEstimate(g,h){if(!g||!h||adults>4)return null;const low=Math.max(12,6+g.outMiles*1.25+g.minutes*.2)+Math.max(12,6+h.backMiles*1.25+(h.backMinutes??h.minutes)*.2),high=low*1.6;return {name:'Uber / Lyft',cost:Math.round((low+high)/2),low:Math.round(low),high:Math.round(high),detail:'No parking required. Actual fares may vary; tips and tolls excluded.',time:duration(g.minutes+(h.backMinutes??h.minutes))+' riding round trip'};}
